mapper.sql:
WHERE b.store_id = #{criteria.storeId}

    AND b.import_type = #{criteria.importType}


    AND b.status = #{criteria.status}


    AND b.data_date >= #{criteria.dataDateFrom}


    AND b.data_date <= #{criteria.dataDateTo}

mapper.select:
SELECT COUNT(*)
FROM import_raw_row r
         JOIN import_batch b ON b.id = r.batch_id AND b.store_id = #{storeId}
WHERE r.batch_id = #{batchId}
  AND r.parse_status <> 'VALID'

SELECT r.`row_number`,
       r.barcode,
       r.parse_status,
       r.error_message
FROM import_raw_row r
         JOIN import_batch b ON b.id = r.batch_id AND b.store_id = #{storeId}
WHERE r.batch_id = #{batchId}
  AND r.parse_status <> 'VALID'
ORDER BY r.`row_number`
LIMIT #{limit} OFFSET #{offset}

SELECT product_id, current_quantity
FROM store_product_inventory
WHERE store_id = #{storeId}
  AND product_id IN

    #{productId}

mapper.update:
UPDATE store_product_inventory
SET current_quantity = current_quantity +


        WHEN #{row.productId} THEN #{row.quantityDelta}


, version = version + 1
WHERE store_id = #{storeId}
  AND product_id IN

    #{row.productId}

UPDATE import_batch
SET status          = 'REVERSED',
    reversed_at     = #{reversedAt},
    reversed_by     = #{reversedBy},
    reversed_reason = #{reversedReason}
WHERE id = #{batchId}
  AND store_id = #{storeId}
  AND status = 'POSTED'
